{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "http_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, attr_span_kind, span_name, COUNT(*) n, ROUND(quantile_cont(duration,0.5)/1e6,2) p50_ms, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE (service_name='ts-seat-service' AND attr_span_kind='Client' AND span_name='GET') OR (service_name='ts-config-service' AND attr_span_kind='Server') GROUP BY 1,2,3", "claim": "Seat's GET calls to config have p95 of hundreds of ms, while config's server spans stay around 3.5 ms."},
        {"kind": "trace", "sql": "SELECT FLOOR(EXTRACT(epoch FROM time - (SELECT MIN(time) FROM abnormal_traces))/30)*30 AS sec, COUNT(*) n, ROUND(quantile_cont(duration,0.5)/1e6,2) p50_ms, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Client' AND span_name='GET' GROUP BY 1 ORDER BY 1", "claim": "Seat's config GET client spans show intermittent 200-700 ms spikes in 30-second windows, with median unchanged near 3.8 ms."},
        {"kind": "trace", "sql": "SELECT service_name, attr_span_kind, COUNT(*) n, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM normal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Client' AND span_name='GET' GROUP BY 1,2 UNION ALL SELECT service_name, attr_span_kind, COUNT(*), ROUND(quantile_cont(duration,0.95)/1e6,1) FROM abnormal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Client' AND span_name='GET' GROUP BY 1,2", "claim": "Seat's config GET client p95 rises from about 4.4 ms in normal to over 200 ms in abnormal."}
      ]
    },
    {
      "service": "ts-travel-plan-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, COUNT(*) n, ROUND(quantile_cont(duration,0.5)/1e6,1) p50_ms, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Internal' GROUP BY 1 ORDER BY 1", "claim": "Travel-plan Internal controller methods show p95 near 4 s while p50 stays about 30-40 ms."},
        {"kind": "trace", "sql": "WITH it AS (SELECT span_id, span_name, duration FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Internal'), chd AS (SELECT parent_span_id pid, SUM(duration) cd FROM abnormal_traces GROUP BY 1) SELECT it.span_name, COUNT(*) slow_n, ROUND(AVG(it.duration/1e6),1) avg_self_total_ms, ROUND(AVG(COALESCE(chd.cd,0)/1e6),1) avg_child_ms FROM it LEFT JOIN chd ON chd.pid=it.span_id WHERE it.duration>1000000000 GROUP BY 1", "claim": "Slow travel-plan method spans average about 4 s total but only a few hundred ms of child-call time."},
        {"kind": "trace", "sql": "SELECT FLOOR(EXTRACT(epoch FROM sv.time - (SELECT MIN(time) FROM abnormal_traces))/60)*60 AS sec, COUNT(*) n, ROUND(quantile_cont(sv.duration,0.5)/1e6,1) p50_ms, ROUND(quantile_cont(sv.duration,0.95)/1e6,1) p95_ms FROM abnormal_traces sv WHERE sv.service_name='ts-travel-plan-service' AND sv.attr_span_kind='Server' GROUP BY 1 ORDER BY 1", "claim": "Travel-plan server p95 jumps from about 47 ms to 2.7-4 s from 120 s onward while p50 stays near 40 ms."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-seat-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT COUNT(*) n, ROUND(quantile_cont(c.duration,0.95)/1e6,1) seat_server_p95_ms, ROUND(quantile_cont(p.duration,0.95)/1e6,1) travel_plan_client_p95_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-travel-plan-service' AND p.attr_span_kind='Client' AND c.service_name='ts-seat-service' AND c.attr_span_kind='Server'", "claim": "Travel-plan's client calls to seat's left_tickets endpoint slow to about 850 ms p95, versus about 10 ms in normal."}
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT src, span_name, COUNT(*) n, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM (SELECT 'normal' src, * FROM normal_traces UNION ALL SELECT 'abnormal', * FROM abnormal_traces) WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%travelPlan%' GROUP BY 1,2 ORDER BY 2,1", "claim": "User-facing ui-dashboard travelPlan cheapest and quickest endpoints have p95 rising to about 4.1 s and 1.2 s."}
      ]
    }
  ]
}
